def resolve_public_attribute(package_name: str, name: str):
    try:
        module_name, attr_name = _LAZY_EXPORTS[name]
    except KeyError as exc:
        raise AttributeError(f"module {package_name!r} has no attribute {name!r}") from exc
    module = import_module(module_name, package_name)
    if name == 'TensorExpr':
        import_module('.semantic_ir', package_name)
    return getattr(module, attr_name)


def chart_property_names(chart: Any) -> tuple[str, ...]:
    return chart.chart_properties()


def mapping_property_names(mapping: object) -> tuple[str, ...]:
    return mapping.map_properties()

